import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

// Helper component for section titles
const SectionTitle = ({ title }) => (
  <h2 className="text-lg font-semibold text-primary mb-6 col-span-full">{title}</h2>
);

// Reusable Form Field Components
const FormInput = ({ label, name, ...props }) => (
  <div>
    <label htmlFor={name} className="block text-sm font-medium text-subtext-light mb-1">{label}</label>
    <input name={name} id={name} {...props} className="w-full bg-background-light dark:bg-gray-800 border-border-light rounded-md shadow-sm" />
  </div>
);
const FormSelect = ({ label, name, children, ...props }) => (
    <div>
        <label htmlFor={name} className="block text-sm font-medium text-subtext-light mb-1">{label}</label>
        <select name={name} id={name} {...props} className="w-full bg-background-light dark:bg-gray-800 border-border-light rounded-md shadow-sm">{children}</select>
    </div>
);

const AddEmployeePage = () => {
  const navigate = useNavigate();

  const [formData, setFormData] = useState({
    firstName: '', lastName: '', personalEmail: '', mobileNumber: '', gender: 'Male',
    employeeId: '', officialEmail: '', department: '', designation: '', joiningDate: '', employeeType: 'Full Time Employees',
    dateOfBirth: '', maritalStatus: 'Single', presentAddress: '', permanentAddress: '',
  });

  const handleChange = (e) => setFormData({ ...formData, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    console.log("Submitting form data:", formData);
    try {
      // You might need to adjust the data sent to match your backend model exactly
      await axios.post('http://127.0.0.1:8000/api/employees/', formData);
      alert('Employee added successfully!');
      navigate('/employees');
    } catch (error) {
      console.error('Error adding employee:', error.response.data);
      alert(`Failed to add staff member: ${JSON.stringify(error.response.data)}`);
    }
  };

  return (
    <div className="p-8">
      <div className="bg-card-light dark:bg-card-dark p-8 rounded-lg shadow-md">
        <h1 className="text-2xl font-bold text-text-light dark:text-text-dark mb-8">Add Employee</h1>

        <form onSubmit={handleSubmit} className="space-y-8">
          {/* Basic Information Section */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-x-8 gap-y-6">
            <SectionTitle title="Basic Information" />

            <div className="lg:col-span-2">
                <label className="block text-sm font-medium text-subtext-light mb-1">Name</label>
                <div className="grid grid-cols-2 gap-4">
                    <input name="firstName" placeholder="First Name" value={formData.firstName} onChange={handleChange} required />
                    <input name="lastName" placeholder="Last Name" value={formData.lastName} onChange={handleChange} required />
                </div>
            </div>
            <div>
                <label className="block text-sm font-medium text-subtext-light mb-1">Gender *</label>
                <div className="flex items-center space-x-4 mt-2">
                    <label><input type="radio" name="gender" value="Male" checked={formData.gender === 'Male'} onChange={handleChange} className="form-radio" /> Male</label>
                    <label><input type="radio" name="gender" value="Female" checked={formData.gender === 'Female'} onChange={handleChange} className="form-radio" /> Female</label>
                </div>
            </div>

            <FormInput label="Personal Email *" name="personalEmail" type="email" value={formData.personalEmail} onChange={handleChange} required />
            <div>
              <label htmlFor="mobileNumber" className="block text-sm font-medium text-subtext-light mb-1">Mobile Number *</label>
              <div className="flex">
                <span className="inline-flex items-center px-3 rounded-l-md border border-r-0 border-border-light bg-gray-50 text-subtext-light text-sm">+91</span>
                <input id="mobileNumber" name="mobileNumber" value={formData.mobileNumber} onChange={handleChange} className="flex-1 min-w-0 block w-full px-3 py-2 rounded-none rounded-r-md" type="text" required />
              </div>
            </div>
          </div>

          {/* Work Information Section */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-x-8 gap-y-6">
            <SectionTitle title="Work Information" />

            <FormInput label="Employee ID *" name="employeeId" value={formData.employeeId} onChange={handleChange} required />
            <FormInput label="Official Email *" name="officialEmail" type="email" value={formData.officialEmail} onChange={handleChange} required />
            <FormInput label="Date of Joining *" name="joiningDate" type="date" value={formData.joiningDate} onChange={handleChange} required />

            <FormSelect label="Department *" name="department" value={formData.department} onChange={handleChange} required>
                <option value="">-Select-</option><option>App Deck</option><option>Engineering</option>
            </FormSelect>
            <FormSelect label="Designation *" name="designation" value={formData.designation} onChange={handleChange} required>
                <option value="">-Select-</option><option>Professor</option><option>Lecturer</option>
            </FormSelect>
            <FormSelect label="Employee Type" name="employeeType" value={formData.employeeType} onChange={handleChange}>
                <option>Full Time Employees</option><option>Part Time</option>
            </FormSelect>
          </div>

          {/* Personal Information Section */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-x-8 gap-y-6">
              <SectionTitle title="Personal Information" />

              <FormInput label="Date of Birth *" name="dateOfBirth" type="date" value={formData.dateOfBirth} onChange={handleChange} required />
              <FormSelect label="Marital Status *" name="maritalStatus" value={formData.maritalStatus} onChange={handleChange} required>
                  <option>Single</option><option>Married</option>
              </FormSelect>
              <div /> {/* Empty div for spacing */}

              <FormInput label="Present Address" name="presentAddress" value={formData.presentAddress} onChange={handleChange} />
              <FormInput label="Permanent Address" name="permanentAddress" value={formData.permanentAddress} onChange={handleChange} />
          </div>

          <div className="mt-10 pt-6 border-t border-border-light flex justify-end gap-4">
            <button type="button" onClick={() => navigate('/employees')}>Cancel</button>
            <button type="submit">Save Employee</button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default AddEmployeePage;
